// Generates src/styles/tokens.css (a Tailwind v4 @theme block) from src/design/tokens.json.
import { readFileSync, writeFileSync } from "node:fs";

const tokens = JSON.parse(readFileSync(new URL("../src/design/tokens.json", import.meta.url), "utf8"));
const lines = [
  "/* Generated by scripts/gen-tokens.mjs from src/design/tokens.json. Do not edit. */",
  "@theme {",
  "  --color-*: initial;",
];
for (const [name, value] of Object.entries(tokens.color)) lines.push(`  --color-${name}: ${value};`);
for (const [name, value] of Object.entries(tokens.radius)) lines.push(`  --radius-${name}: ${value};`);
for (const [name, value] of Object.entries(tokens.shadow)) lines.push(`  --shadow-${name}: ${value};`);
for (const [name, value] of Object.entries(tokens.font)) lines.push(`  --font-${name}: ${value};`);
lines.push("}", "");
writeFileSync(new URL("../src/styles/tokens.css", import.meta.url), lines.join("\n"));
